class HcodeFileReader {

    constructor(inputEl, imgEl){

        this.inputEl = inputEl;
        this.imgEl = imgEl;

        this.initInputEvent();

    }

    initInputEvent(){

        document.querySelector(this.inputEl).addEventListener('change', e=> {

            this.reader(e.target.files[0]).then(result => {

                document.querySelector(this.imgEl).src = result;

            });

        });

    }

    reader(file){

        return new Promise((resolve, reject) => {

            let reader = new FileReader();

            reader.onload = function(){
    
                resolve(reader.result);
    
            }

            reader.onerror = function(){

                reject('Não foi possível ler a imagem.');

            }
    
            reader.readAsDataURL(file);

        });       

    } 


}

HTMLFormElement.prototype.save = function(config){

  let form = this;

  form.addEventListener('submit', e=> {

    e.preventDefault();
  
    let formData = new FormData(form);
  
    fetch(form.action, {
  
      method:form.method,
      body: formData
  
    })
      .then(response => response.json())
      .then(json => {

        if(json.error){         
          if(typeof config.failure === 'function') config.failure(json.error);
        } else {
          if(typeof config.success === 'function') config.success(json);
        }        

      }).catch(err => {

        if(typeof config.failure === 'function') config.failure(err);

      });

  });
    
}

class HcodeGrid {

    constructor(configs){

        configs.listeners = Object.assign({
            afterUpdateClick:(e)=>{
                $('#modal-update').modal('show');
            },
            afterDeleteClick:(e)=>{
                window.location.reload();      
            },
            afterFormCreate: (e) => {
                window.location.reload();
            },
            afterFormUpdate: (e) => {
                window.location.reload();
            },
            afterFormCreateError: (e) => {
                alert('Não foi possível enviar o formulário!');
            },
            afterFormUpdateError: (e) => {
                alert('Não foi possível enviar o formulário!');
            }                       
        }, configs.listeners);

        this.options = Object.assign({}, {
            formCreate:'#modal-create form',
            formUpdate:'#modal-update form',
            btnUpdate:'btn-update',
            btnDelete:'btn-delete',
            onUpdateLoad: (form, name, data) => {

                let input = form.querySelector('[name=' + name + ']');

                if(input) input.value = data[name];

            }           
        }, configs);

        this.rows = [...document.querySelectorAll('table tbody tr')];

        this.initForms();
        this.initButtons();
    }

    initForms(){

        this.formCreate = document.querySelector(this.options.formCreate);

        if(this.formCreate){

            this.formCreate.save({
                success:()=>{
                    this.fireEvent('afterFormCreate');
                },
                failure:()=>{
                    this.fireEvent('afterFormCreateError');   
                }     

            });

        }

        if(this.formUpdate){
      
            this.formUpdate = document.querySelector(this.options.formUpdate);
        
            this.formUpdate.save({
                success:()=>{
                    this.fireEvent('afterFormUpdate');
                },
                failure:()=>{
                    this.fireEvent('afterFormUpdateError');
                }      

            });
            
        }

    }

    fireEvent(name, args){

        if(typeof this.options.listeners[name] === 'function') this.options.listeners[name].apply(this, args);

    }

    getTrData(e){

        let tr = e.path.find(el => {
        
            return (el.tagName.toUpperCase() === 'TR');

        });

        return JSON.parse(tr.dataset.row);

    }

    btnUpdateClick(e){

        this.fireEvent('beforeUpdateClick', [e]);
      
        let data = this.getTrData(e);

        for (let name in data){

            this.options.onUpdateLoad(this.formUpdate, name, data);     

        }      
       
        this.fireEvent('afterUpdateClick', [e]);

    }

    btnDeleteClick(e){

        this.fireEvent('beforeDeleteClick');  
      
        let data = this.getTrData(e);

        if(confirm(eval('`' + this.options.deleteMsg + '`'))){

            fetch(eval('`' + this.options.deleteUrl + '`'), {
                method:'DELETE'

            })
             .then(response => response.json())
             .then(json => {

                    this.fireEvent('afterDeleteClick');      
                   
                });


        }

    }

    initButtons(){  
        
        this.rows.forEach(row => {

            [...row.querySelectorAll('.btn')].forEach(btn => {

                btn.addEventListener('click', e => {

                    if(e.target.classList.contains(this.options.btnUpdate)) {

                        this.btnUpdateClick(e);

                    } else if (e.target.classList.contains(this.options.btnDelete)){

                        this.btnDeleteClick(e);

                    } else {

                        this.fireEvent('buttonClick', [e.target, this.getTrData(e), e]);

                    }

                });

            });

        });    

    }

}

